async function privateFromMnemonic(raw){if(!window.LaunchMnemonic)throw Error('Recovery phrase support failed to load. Hard-refresh this page.');const mnemonic=window.LaunchMnemonic.normalize(raw);if(mnemonic.split(/\s+/).length!==12||!window.LaunchMnemonic.validate(mnemonic))throw Error('Invalid 12-word BIP39 recovery phrase.');let I=await hmac512(te.encode('ed25519 seed'),await window.LaunchMnemonic.toSeed(mnemonic)),key=I.slice(0,32),chain=I.slice(32);for(const i of MNEMONIC_PATH){const data=new Uint8Array(37);data[0]=0;data.set(key,1);data.set(hardIndex(i),33);I=await hmac512(chain,data);key=I.slice(0,32);chain=I.slice(32)}return{privateKey:await canonicalPrivate(bytesHex(key)),mnemonic}}
async function secretFromText(text){let raw=String(text||'').trim(),mnemonic='';try{const j=JSON.parse(raw);const fileMnemonic=j.mnemonic||j.recoveryPhrase||'';const fileKey=j.privateKeyHex||j.privateKey||j.key||j.secret||'';if(fileMnemonic){const derived=await privateFromMnemonic(fileMnemonic);if(fileKey&&await canonicalPrivate(fileKey)!==derived.privateKey)throw Error('Backup file recovery phrase does not match its private key.');return derived}raw=fileKey||raw}catch(e){if(e instanceof SyntaxError){}else throw e}if(raw.split(/\s+/).length===12&&!/^(?:ed)?[0-9a-f]+$/i.test(raw)){const derived=await privateFromMnemonic(raw);return derived}return{privateKey:await canonicalPrivate(raw),mnemonic}}
function backupJson(pair){const out={format:'launch-cluster-hotpocket-admin-v2',privateKeyHex:pair.textPrivate,publicKeyHex:pair.textPublic};if(currentMnemonic){out.mnemonic=currentMnemonic;out.derivation=MNEMONIC_DERIVATION}return JSON.stringify(out,null,2)}
function renderMnemonic(){const box=$('lcMnemonicBox'),words=$('lcMnemonicWords');if(!box||!words)return;box.hidden=!currentMnemonic;words.textContent=currentMnemonic||''}
async function sodiumReady(){if(window.sodium?.ready)await sodium.ready;if(!window.sodium?.crypto_sign_seed_keypair)throw Error('Cryptography failed to initialize.')}
async function canonicalPrivate(raw){await sodiumReady();let v=String(raw||'').trim().toLowerCase().replace(/^0x/,'');if(v.startsWith('ed'))v=v.slice(2);let sk;if(/^[0-9a-f]{128}$/.test(v))sk=hexBytes(v);else if(/^[0-9a-f]{64}$/.test(v))sk=sodium.crypto_sign_seed_keypair(hexBytes(v)).privateKey;else throw Error("Invalid key type. Expected an 'ed' HotPocket private key or Ed25519 seed.");return'ed'+bytesHex(sk)}
async function hpPair(raw){await sodiumReady();const text=await canonicalPrivate(raw),sk=hexBytes(text.slice(2)),pk=sk.slice(32),priv=new Uint8Array(65),pub=new Uint8Array(33);priv[0]=0xed;pub[0]=0xed;priv.set(sk,1);pub.set(pk,1);return{privateKey:priv,publicKey:pub,textPrivate:text,textPublic:'ed'+bytesHex(pk)}}
function keyText(){return localStorage.getItem(DEVICE_KEY)||''}
function download(name,body){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type:'application/json'}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function decode(raw){try{if(raw instanceof ArrayBuffer)return BSON.deserialize(new Uint8Array(raw));if(raw instanceof Uint8Array)return BSON.deserialize(raw);if(raw?.buffer)return BSON.deserialize(new Uint8Array(raw.buffer,raw.byteOffset||0,raw.byteLength||raw.buffer.byteLength))}catch{}return null}
async function firstAdminAction(pair){
  const endpoint=relayEndpoint(),actionId=`launch-admin-${Date.now()}-${crypto.getRandomValues(new Uint32Array(1))[0].toString(16)}`;
  const client=await HotPocket.createClient([endpoint],{privateKey:pair.privateKey,publicKey:pair.publicKey},{protocol:HotPocket.protocols.bson,requiredConnectionCount:1,connectionTimeoutMs:10000});
  let timer;try{if(!(await client.connect()))throw Error(`Could not connect to ${endpoint}.`);const out=new Promise((resolve,reject)=>{timer=setTimeout(()=>reject(Error('Timed out waiting for first-admin consensus result.')),40000);client.on(HotPocket.events.contractOutput,result=>{const blobs=Array.isArray(result?.outputs)?result.outputs:(Array.isArray(result)?result:[result]);for(const raw of blobs){const obj=decode(raw);if(obj?.actionId===actionId){clearTimeout(timer);obj.type==='error'?reject(Error(obj.error||'Contract error')):resolve(obj)}}})});const sub=await client.submitContractInput(BSON.serialize({type:'bootstrap-head-admin',actionId,method:'everstoring',publicKey:pair.textPublic}),undefined,10,true);if(sub?.submissionStatus){const s=await sub.submissionStatus;if(s?.status!=='accepted')throw Error(s?.reason||'HotPocket rejected first-admin input.')}return await out}finally{clearTimeout(timer);try{await client.close()}catch{}}
}
async function directConsensusAction(type,payload={}){
  const pair=await hpPair(keyText()),endpoint=relayEndpoint(),actionId=`launch-${type}-${Date.now()}-${crypto.getRandomValues(new Uint32Array(1))[0].toString(16)}`;
  const client=await HotPocket.createClient([endpoint],{privateKey:pair.privateKey,publicKey:pair.publicKey},{protocol:HotPocket.protocols.bson,requiredConnectionCount:1,connectionTimeoutMs:10000});let timer;
  try{if(!(await client.connect()))throw Error(`Could not connect to ${endpoint}.`);const out=new Promise((resolve,reject)=>{timer=setTimeout(()=>reject(Error(`Timed out waiting for ${type} consensus result.`)),45000);client.on(HotPocket.events.contractOutput,result=>{const blobs=Array.isArray(result?.outputs)?result.outputs:(Array.isArray(result)?result:[result]);for(const raw of blobs){const obj=decode(raw);if(obj?.actionId===actionId){clearTimeout(timer);obj.type==='error'?reject(Error(obj.error||'Contract error')):resolve(obj)}}})});const sub=await client.submitContractInput(BSON.serialize({type,actionId,...payload}),undefined,10,true);if(sub?.submissionStatus){const st=await sub.submissionStatus;if(st?.status!=='accepted')throw Error(st?.reason||'HotPocket rejected the consensus input.')}return await out}finally{clearTimeout(timer);try{await client.close()}catch{}}
}
async function markPortalFinalizedOnce(){
  if(portalMarked||portalMarkBusy)return portalMarked;portalMarkBusy=true;
  try{const r=await directConsensusAction('launch-portal-finalize');portalMarked=!!r?.portalFinalized;if(portalMarked){notice('lcFinalizeStatus','Final handover is complete and consensus has activated the storage portal.','good');sessionStorage.setItem('lc-final-reload','1');setTimeout(()=>location.reload(),1800)}return portalMarked}
  catch(e){notice('lcFinalizeStatus',`Master key is disabled, but portal activation has not committed yet: ${e.message}`,'bad');return false}
  finally{portalMarkBusy=false}
}
function notice(id,msg,kind=''){const e=$(id);if(!e)return;e.textContent=msg;e.className=`note ${kind==='bad'?'badbox':kind==='good'?'goodbox':''}`}
function findCard(prefix){return[...document.querySelectorAll('.grid > section.card')].find(x=>String(x.querySelector('h2')?.textContent||'').trim().startsWith(prefix))}
function build(){if($('lcWizard'))return;const wrap=document.querySelector('.wrap'),top=document.querySelector('.top'),grid=document.querySelector('.grid'),auth=document.querySelector('.auth'),state=findCard('Cluster state'),wallet=findCard('1. Cluster treasury'),settings=findCard('2. Cluster settings'),deploy=findCard('3. Bootstrap'),activity=findCard('Activity');if(!wrap||!top||!grid||!wallet||!settings||!state||!deploy||!activity)return;
  top.querySelector('.brand h1').textContent='Launch Cluster';top.querySelector('.brand p').textContent='Build the cluster, watch every validator join, then hand control to the managed fleet.';auth.style.display='none';grid.style.display='none';
  const w=document.createElement('div');w.id='lcWizard';w.innerHTML=`<div class="lc-stepper"><button data-step="1"><span>1</span>Admin key</button><button data-step="2"><span>2</span>Fund wallet</button><button data-step="3"><span>3</span>Cluster size</button><button data-step="4"><span>4</span>Eligible nodes</button><button data-step="5"><span>5</span>Deploy + finalize</button></div>
  <section class="lc-step" data-panel="1"><div class="lc-step-head"><small>STEP 1</small><h2>Create the administrator</h2><p>The first person to connect becomes head admin. Generate a 12-word recovery phrase or import an existing backup, then connect with that exact identity.</p></div><div id="lcStep1"></div></section>
  <section class="lc-step" data-panel="2"><div class="lc-step-head"><small>STEP 2</small><h2>Generate or import the Xahau treasury</h2><p>Fund it with XAH. The wizard detects the validated balance, creates the EVR trustline automatically, then waits for EVR before continuing.</p></div><div id="lcStep2"></div></section>
  <section class="lc-step" data-panel="3"><div class="lc-step-head"><small>STEP 3</small><h2>Choose cluster size and signer quorum</h2><p>Choose exactly one topology: 2 signers / 3 managed instances, or 3 signers / 5 managed instances.</p></div><div id="lcStep3"></div></section>
  <section class="lc-step" data-panel="4"><div class="lc-step-head"><small>STEP 4</small><h2>Build the eligible host pool</h2><p>Select as many evrPanel candidates as you want. They are an eligible queue; bad hosts can be skipped until the target number of good managed instances has qualified.</p></div><div id="lcStep4"></div></section>
  <section class="lc-step" data-panel="5"><div class="lc-step-head"><small>STEP 5</small><h2>Deploy, watch every stage, then finalize</h2><p>The deployment view is driven by the real acquisition, READY, UNL, signer and handover state.</p></div><div id="lcStep5"></div></section>`;top.insertAdjacentElement('afterend',w);
  buildStep1();buildStep2(wallet);buildStep3();buildStep4(settings);buildStep5(state,deploy,activity);installSky();document.querySelector('.lc-stepper').onclick=e=>{const b=e.target.closest('[data-step]');if(b&&!b.disabled)switchStep(Number(b.dataset.step))};
  switchStep(1);selectedFromTextarea();enrichHosts();
}
function buildStep1(){const root=$('lcStep1');root.innerHTML=`<div class="lc-admin-grid"><section class="card"><h2>HotPocket administrator identity</h2><p class="sub">Generate a standard 12-word recovery phrase. It deterministically restores the exact same HotPocket Ed25519 key, and the downloaded backup file contains the key too.</p><div id="lcKeyStatus" class="note warnbox">No key loaded.</div><div id="lcMnemonicBox" class="lc-mnemonic-box" hidden><small>12-WORD RECOVERY PHRASE — KEEP PRIVATE</small><div id="lcMnemonicWords" class="lc-mnemonic-words"></div><button id="lcCopyMnemonic" type="button">Copy phrase</button></div><div class="actions"><button id="lcGenKey" class="primary">Generate 12 words + key</button><button id="lcSaveKey">Download backup</button><label class="btn ghost lc-file-button">Import backup file<input id="lcImportKey" type="file" accept=".json,.txt,.key"></label></div><div class="lc-seed-restore"><label for="lcSeedPhrase">Restore from 12 words</label><textarea id="lcSeedPhrase" rows="3" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="word1 word2 … word12"></textarea><button id="lcImportMnemonic" type="button">Restore identity</button></div><label class="checkrow lc-backup"><input id="lcBackup" type="checkbox"> I have saved the recovery phrase or backup file somewhere safe.</label><button id="lcClaim" class="primary lc-big-button" disabled>Connect & become first admin</button><div id="lcClaimStatus" class="mini">Waiting for a saved identity.</div></section><section class="card"><h2>One identity, two recovery methods</h2><p>The 12 words and the JSON backup both restore the same HotPocket key. The phrase uses BIP39 plus hardened SLIP-0010 Ed25519 derivation, so typing the same 12 words always recreates the same identity.</p><p class="sub">The phrase is never sent to the server. Only the derived key is kept in this browser. Treat either the phrase or backup file as the administrator secret.</p></section></div><div class="lc-step-footer"><span id="lcStep1Gate">Save the recovery phrase or backup file, then connect as first admin.</span><button id="lcStep1Next" class="primary" disabled>Next: fund wallet →</button></div>`;
  $('lcBackup').checked=localStorage.getItem(BACKUP_KEY)==='1';$('lcBackup').onchange=()=>{localStorage.setItem(BACKUP_KEY,$('lcBackup').checked?'1':'0');syncKey()};
  $('lcGenKey').onclick=async()=>{const b=$('lcGenKey'),old=b.textContent;b.disabled=true;b.innerHTML='<span class="spinner"></span>Generating…';try{if(!window.LaunchMnemonic)throw Error('Recovery phrase support is unavailable. Hard-refresh this page.');currentMnemonic=window.LaunchMnemonic.generate();const derived=await privateFromMnemonic(currentMnemonic);localStorage.setItem(DEVICE_KEY,derived.privateKey);localStorage.removeItem(BACKUP_KEY);$('lcBackup').checked=false;renderMnemonic();await syncKey();$('lcSaveKey').click()}catch(e){notice('lcClaimStatus',e.message,'bad')}finally{b.disabled=false;b.textContent=old}};
  $('lcSaveKey').onclick=async()=>{try{const p=await hpPair(keyText());download(`launch-cluster-admin-${p.textPublic.slice(0,14)}.json`,backupJson(p));$('lcBackup').checked=true;localStorage.setItem(BACKUP_KEY,'1');syncKey()}catch(e){notice('lcClaimStatus',e.message,'bad')}};
  $('lcImportKey').onchange=async e=>{try{const t=await e.target.files?.[0]?.text();if(!t)return;const loaded=await secretFromText(t);currentMnemonic=loaded.mnemonic||'';localStorage.setItem(DEVICE_KEY,loaded.privateKey);$('lcBackup').checked=true;localStorage.setItem(BACKUP_KEY,'1');renderMnemonic();await syncKey();notice('lcClaimStatus',currentMnemonic?'Recovery phrase + backup loaded. You can connect now.':'Backup key loaded. You can connect now.')}catch(x){notice('lcClaimStatus',x.message,'bad')}e.target.value=''};
  $('lcImportMnemonic').onclick=async()=>{try{const loaded=await privateFromMnemonic($('lcSeedPhrase').value);currentMnemonic=loaded.mnemonic;localStorage.setItem(DEVICE_KEY,loaded.privateKey);$('lcBackup').checked=true;localStorage.setItem(BACKUP_KEY,'1');renderMnemonic();await syncKey();notice('lcClaimStatus','Recovery phrase restored the administrator identity.','good')}catch(e){notice('lcClaimStatus',e.message,'bad')}};
  $('lcCopyMnemonic').onclick=async()=>{if(!currentMnemonic)return;try{await navigator.clipboard.writeText(currentMnemonic);notice('lcClaimStatus','Recovery phrase copied. Keep it private.','good')}catch{notice('lcClaimStatus','Could not access the clipboard. Copy the words manually.','bad')}};
  $('lcClaim').onclick=async()=>{const b=$('lcClaim'),old=b.textContent;b.disabled=true;b.innerHTML='<span class="spinner"></span>Connecting to HotPocket…';try{try{lastState=await window.refresh(true);adminVerified=true}catch{const pair=await hpPair(keyText());const r=await firstAdminAction(pair);notice('lcClaimStatus',r.message||'First administrator created.','good');await sleep(4500);lastState=await window.refresh(true);adminVerified=true}notice('lcClaimStatus','Connected as head admin.','good');startPoll();sync(lastState)}catch(e){adminVerified=false;notice('lcClaimStatus',e.message,'bad')}finally{b.textContent=old;syncKey()}};
  $('lcStep1Next').onclick=()=>switchStep(2);renderMnemonic();syncKey();
}
async function syncKey(){const raw=keyText(),saved=$('lcBackup')?.checked;let ok=false,pub='';try{if(raw){const p=await hpPair(raw);pub=p.textPublic;ok=true}}catch{}const st=$('lcKeyStatus');if(st){st.className=`note ${ok?'':'warnbox'}`;st.innerHTML=ok?`Key loaded: <span class="mono">${esc(pub)}</span>${saved?' · backup confirmed':' · save a backup before connecting'}`:'No valid HotPocket key loaded.'}if($('lcSaveKey'))$('lcSaveKey').disabled=!ok;if($('lcClaim'))$('lcClaim').disabled=!(ok&&saved)||adminVerified;if($('lcStep1Next'))$('lcStep1Next').disabled=!adminVerified;if($('lcStep1Gate'))$('lcStep1Gate').textContent=adminVerified?'Connected as head admin.':'Save the recovery phrase or backup file, then connect as first admin.'}
function walletReady(w={}){return!!w.generated&&!!w.seedPresent&&!!w.exists&&!!w.evrTrustline&&Number(w.evrBalance)>0}
async function autoTrust(d){const w=d?.wallet||{};if(!adminVerified||trustBusy||!w.generated||!w.seedPresent||!w.exists||w.evrTrustline)return;const b=$('trust');if(!b||b.disabled)return;trustBusy=true;try{b.click();await sleep(5000)}finally{trustBusy=false}}
function syncWallet(d){const w=d?.wallet||{},vals=[!!w.generated,!!w.exists,!!w.evrTrustline,Number(w.evrBalance)>0];['lcW1','lcW2','lcW3','lcW4'].forEach((id,i)=>$(id)?.classList.toggle('done',vals[i]));const ready=adminVerified&&walletReady(w);if($('lcStep2Next'))$('lcStep2Next').disabled=!ready;if($('lcStep2Gate'))$('lcStep2Gate').textContent=ready?'Treasury funded and ready.':'Fund XAH, wait for the automatic EVR trustline, then fund EVR.';if(adminVerified)autoTrust(d).catch(()=>{})}
function buildStep2(wallet){const root=$('lcStep2');wallet.classList.add('wide','lc-native-card');const tracker=document.createElement('div');tracker.className='lc-wallet-tracker';tracker.innerHTML=`<div id="lcW1" class="lc-track"><i></i><span><b>Wallet ready</b><small>Generate or import treasury</small></span></div><div id="lcW2" class="lc-track"><i></i><span><b>XAH detected</b><small>Validated ledger account active</small></span></div><div id="lcW3" class="lc-track"><i></i><span><b>EVR trustline</b><small>Created automatically</small></span></div><div id="lcW4" class="lc-track"><i></i><span><b>EVR detected</b><small>Treasury ready</small></span></div>`;wallet.insertAdjacentElement('afterbegin',tracker);root.appendChild(wallet);const foot=document.createElement('div');foot.className='lc-step-footer';foot.innerHTML=`<button id="lcBack2" class="ghost">← Back</button><span id="lcStep2Gate">Generate/import the wallet and complete funding.</span><button id="lcStep2Next" class="primary" disabled>Next: cluster size →</button>`;root.appendChild(foot);$('lcBack2').onclick=()=>switchStep(1);$('lcStep2Next').onclick=()=>switchStep(3)}
function buildStep3(){const r=$('lcStep3');r.innerHTML=`<div class="lc-topology-grid"><button class="lc-topology" data-target="3" data-quorum="2"><span class="lc-topology-title">2 signers · 3 instances</span><span class="lc-topology-copy">Three managed validators after finalization. Two signer approvals control the treasury.</span><span class="lc-topology-state">Choose this topology</span></button><button class="lc-topology" data-target="5" data-quorum="3"><span class="lc-topology-title">3 signers · 5 instances</span><span class="lc-topology-copy">Five managed validators after finalization. Three signer approvals control the treasury.</span><span class="lc-topology-state">Choose this topology</span></button></div><div class="note">During deployment Bootstrap A temporarily remains in the UNL. It is removed only in the final handover after the managed fleet is ready.</div><div class="lc-step-footer"><button id="lcBack3" class="ghost">← Back</button><span id="lcTopologyStatus">Choose one option.</span><button id="lcNext3" class="primary" disabled>Next: eligible nodes →</button></div>`;$('lcBack3').onclick=()=>switchStep(2);$('lcNext3').onclick=()=>switchStep(4);for(const b of r.querySelectorAll('.lc-topology'))b.onclick=()=>chooseTopology(b)}
async function chooseTopology(b){for(const x of document.querySelectorAll('.lc-topology'))x.disabled=true;b.classList.add('loading');b.querySelector('.lc-topology-state').textContent='Saving selection…';try{$('target').value=b.dataset.target;$('quorum').value=b.dataset.quorum;for(const e of [$('target'),$('quorum')]){e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}))}const saved=await window.adminApi('cluster-settings',window.collect());window.applySettings?.(saved.settings,true);localStorage.setItem(TOPOLOGY_KEY,`${b.dataset.target}/${b.dataset.quorum}`);lastState=await window.refresh(true);syncTopology()}catch(e){notice('lcTopologyStatus',e.message,'bad')}finally{b.classList.remove('loading');for(const x of document.querySelectorAll('.lc-topology'))x.disabled=false;syncTopology()}}
function syncTopology(){const t=Number($('target')?.value),q=Number($('quorum')?.value),chosen=localStorage.getItem(TOPOLOGY_KEY)===`${t}/${q}`&&((t===3&&q===2)||(t===5&&q===3));for(const b of document.querySelectorAll('.lc-topology')){const a=Number(b.dataset.target)===t&&Number(b.dataset.quorum)===q;b.classList.toggle('selected',a&&chosen);if(!b.classList.contains('loading'))b.querySelector('.lc-topology-state').textContent=a&&chosen?'Selected':'Choose this topology'}$('lcNext3').disabled=!chosen;$('lcTopologyStatus').textContent=chosen?`${q} signers / ${t} managed instances selected.`:'Choose one option.'}
function selectedFromTextarea(){for(const h of String($('hosts')?.value||'').split(/[\s,]+/).filter(Boolean))selected.add(h)}
function scheduleHostEnrich(){if(currentStep!==4||hostEnrichQueued)return;hostEnrichQueued=true;requestAnimationFrame(()=>{hostEnrichQueued=false;try{enrichHosts()}catch(e){console.warn('Host enrichment failed',e)}})}
const originalFetch=window.fetch.bind(window);window.fetch=async(...args)=>{const r=await originalFetch(...args);try{const u=String(args[0] instanceof Request?args[0].url:args[0]||'');if(currentStep===4&&/\/hosts(?:\?|\/search\?)/i.test(u))r.clone().json().then(j=>{for(const h of Array.isArray(j?.hosts)?j.hosts:[])if(h?.address)hostMeta.set(String(h.address),h);scheduleHostEnrich()}).catch(()=>{})}catch{}return r};
function flag(c){c=String(c||'').toUpperCase();return/^[A-Z]{2}$/.test(c)?String.fromCodePoint(...[...c].map(x=>127397+x.charCodeAt(0))):'🌐'}
function cpu(h){const c=h?.cpuCores??h?.cpuCount??h?.cores??h?.vcpu??h?.vcpus,m=h?.cpuModel??h?.processor??h?.cpu;if(c!=null&&typeof m==='string')return`${c} · ${m}`;if(c!=null)return`${c} cores`;return typeof m==='string'?m:'—'}
