async function sha256Hex(bytes){return bytesHex(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)))}
function managedProxyBase(n){return n?.pubkey?`${location.origin}/api/managed-node/${encodeURIComponent(n.pubkey)}`:null}
async function signedManagedAi(n,path,json={}){
  const pair=await hpPair(keyText()),raw=te.encode(JSON.stringify(json)),ts=Date.now(),digest=await sha256Hex(raw),msg=`launch-node-v1|POST|${path}|${ts}|${digest}`,sig=bytesHex(sodium.crypto_sign_detached(te.encode(msg),hexBytes(pair.textPrivate.slice(2)))),headers={'Content-Type':'application/json','X-Launch-Public-Key':pair.textPublic,'X-Launch-Timestamp':String(ts),'X-Launch-Signature':sig};
  const r=await fetch(managedProxyBase(n)+path,{method:'POST',headers,body:raw}),text=await r.text();let out={};try{out=text?JSON.parse(text):{}}catch{out={error:text||`HTTP ${r.status}`}}if(!r.ok||out.ok===false)throw Error(out.error||`HTTP ${r.status}`);return out;
}
async function managedAiStatus(n){const r=await fetch(managedProxyBase(n)+'/api/launch/ai/status',{cache:'no-store'}),j=await r.json().catch(()=>null);if(!r.ok||!j)throw Error(j?.error||`AI status HTTP ${r.status}`);return j}
function setPrefinalAiInstallBusy(on){prefinalAiInstallBusy=!!on;const install=$('lcInstallSelectedAi'),cont=$('lcEndpointContinue'),fin=$('lcFinalize');if(install)install.disabled=prefinalAiInstallBusy;if(cont){cont.disabled=prefinalAiInstallBusy;cont.classList.toggle('is-loading',prefinalAiInstallBusy);cont.setAttribute('aria-busy',prefinalAiInstallBusy?'true':'false')}if(fin){fin.disabled=prefinalAiInstallBusy||fin.disabled;fin.classList.toggle('lc-ai-install-lock',prefinalAiInstallBusy);if(prefinalAiInstallBusy)fin.title='AI installation is in progress. Finish or fail the install before finalizing.';else fin.removeAttribute('title')}if(!prefinalAiInstallBusy&&lastState)sync(lastState)}
function prefinalDiversityDefaults(i){
  const temps=[0.15,0.2,0.25,0.18],profiles=['broad','content','discovery','balanced'];
  return{temperature:temps[i%temps.length],profile:profiles[i%profiles.length]};
}
function prefinalModelOptions(models,selected,fallback){
  const all=[...new Set([selected,fallback,...(Array.isArray(models)?models:[])].filter(Boolean))];
  return all.map(m=>`<option value="${esc(m)}"></option>`).join('');
}
async function hydratePrefinalAiRows(fleet){
  const fallback=String($('lcPreFinalizeAiModel')?.value||localStorage.getItem('launchAiDefaultModel')||'qwen3:0.6b').trim()||'qwen3:0.6b';
  await Promise.all(fleet.map(async(n,i)=>{
    const row=document.querySelector(`[data-ai-config-row="${i}"]`);if(!row)return;
    const note=row.querySelector('[data-ai-node-note]'),model=row.querySelector('[data-ai-model]'),modelList=row.querySelector('[data-ai-model-list]'),temp=row.querySelector('[data-ai-temp]'),profile=row.querySelector('[data-ai-profile]'),seed=row.querySelector('[data-ai-seed]');
    try{
      const st=await managedAiStatus(n),d=prefinalDiversityDefaults(i),chosen=st.taggingModel&&st.models?.includes(st.taggingModel)?st.taggingModel:fallback;
      if(modelList)modelList.innerHTML=prefinalModelOptions(st.models,chosen,fallback);model.value=chosen;
      temp.value=String(st.taggingConfigured?st.taggingTemperature:d.temperature);
      profile.value=st.taggingConfigured?st.taggingProfile:d.profile;
      seed.value=String(Number.isInteger(Number(st.taggingSeed))?Number(st.taggingSeed):0);
      note.textContent=st.installed?`${st.models?.length||0} model${(st.models?.length||0)===1?'':'s'} installed · ${st.running?'Ollama running':'Ollama stopped'}`:'Ollama not installed yet';
    }catch(e){const d=prefinalDiversityDefaults(i);if(modelList)modelList.innerHTML=prefinalModelOptions([],fallback,fallback);model.value=fallback;temp.value=String(d.temperature);profile.value=d.profile;note.textContent=`Status unavailable: ${e.message}`}
  }));
}
function applyPrefinalDefaultModel(){
  const value=String($('lcPreFinalizeAiModel')?.value||'').trim();if(!value||!/^[a-zA-Z0-9._:/-]{1,128}$/.test(value))return;
  localStorage.setItem('launchAiDefaultModel',value);
  document.querySelectorAll('[data-ai-validator]:checked').forEach(c=>{const row=document.querySelector(`[data-ai-config-row="${c.dataset.aiValidator}"]`),input=row?.querySelector('[data-ai-model]');if(input)input.value=value});
}
async function installSelectedAi(){
  const modal=$('lcFinalizeEndpointsModal'),checks=[...modal.querySelectorAll('[data-ai-validator]:checked')],status=$('lcPreFinalizeAiStatus');
  if(!checks.length){if(status)status.textContent='Choose at least one validator.';return}
  setPrefinalAiInstallBusy(true);
  try{
    const participants=[];
    for(let pos=0;pos<checks.length;pos++){
      const idx=Number(checks[pos].dataset.aiValidator),n=fleetView(lastState||{}).fleet[idx],row=modal.querySelector(`[data-ai-config-row="${idx}"]`);if(!n||!row)continue;
      const model=String(row.querySelector('[data-ai-model]')?.value||'').trim(),temperature=Number(row.querySelector('[data-ai-temp]')?.value),profile=String(row.querySelector('[data-ai-profile]')?.value||'balanced'),seed=Number(row.querySelector('[data-ai-seed]')?.value);
      if(!/^[a-zA-Z0-9._:/-]{1,128}$/.test(model))throw Error(`${n.domain||n.pubkey}: choose a valid model.`);
      if(!Number.isFinite(temperature)||temperature<0||temperature>2)throw Error(`${n.domain||n.pubkey}: temperature must be between 0 and 2.`);
      if(!['balanced','broad','content','discovery'].includes(profile))throw Error(`${n.domain||n.pubkey}: choose a valid tagging style.`);
      if(status)status.textContent=`${pos+1}/${checks.length}: preparing AI on ${n.domain||String(n.pubkey).slice(0,12)}…`;
      let st=await managedAiStatus(n).catch(()=>null);
      if(!st?.installed){
        await signedManagedAi(n,'/api/launch/ai/install',{});
        for(let tries=0;tries<240;tries++){await sleep(5000);st=await managedAiStatus(n);if(st.installed&&!st.installing)break;if(!st.installing&&st.installResult&&String(st.installResult).startsWith('failed'))throw Error(`${n.domain}: ${st.installResult}`)}
        if(!st?.installed)throw Error(`${n.domain}: Ollama install did not complete.`);
      }
      if(!Array.isArray(st.models)||!st.models.includes(model)){
        if(status)status.textContent=`${pos+1}/${checks.length}: pulling ${model} on ${n.domain||String(n.pubkey).slice(0,12)}…`;
        await signedManagedAi(n,'/api/launch/ai/pull',{model});
      }
      if(status)status.textContent=`${pos+1}/${checks.length}: activating ${model} · temp ${temperature} · ${profile}…`;
      await signedManagedAi(n,'/api/launch/ai/tagging-config',{model,temperature,profile,seed:Number.isInteger(seed)&&seed>=0?seed:undefined});
      participants.push(n.pubkey);
      localStorage.setItem('launchAiDefaultModel',model);
      const note=row.querySelector('[data-ai-node-note]');if(note)note.textContent=`Ready · ${model} · temperature ${temperature} · ${profile}`;
    }
    if(status)status.textContent='Recording the selected AI validator set in HotPocket consensus…';
    await directConsensusAction('launch-ai-participants-set',{participants});
    if(status)status.textContent=`AI ready on ${participants.length} selected validator${participants.length===1?'':'s'}. Each has its own active model/sampling profile. HotPocket will collect exactly 5 suggestions from each responding AI, then open the full ballot for voting.`;
  }catch(e){if(status)status.textContent=`AI install stopped: ${e.message}`}finally{setPrefinalAiInstallBusy(false)}
}

