  if(!modal){modal=document.createElement('div');modal.id='lcFinalizeEndpointsModal';modal.className='lc-endpoint-modal';modal.hidden=true;modal.innerHTML=`<div class="lc-endpoint-backdrop"></div><section class="lc-endpoint-card" role="dialog" aria-modal="true" aria-labelledby="lcEndpointTitle"><div class="lc-endpoint-head"><div><small>BEFORE FINALIZATION</small><h2 id="lcEndpointTitle">Save endpoints + optional AI install</h2><p>Bootstrap A is about to be removed. Save the managed gptcp1 addresses and optionally install AI on selected validators first.</p></div><button id="lcEndpointClose" class="ghost" type="button" aria-label="Close">✕</button></div><div id="lcEndpointList" class="lc-endpoint-list"></div><textarea id="lcEndpointCopyText" class="lc-endpoint-copy-text" readonly hidden></textarea><div class="lc-prefinal-ai"><h3>Optional: Install + configure AI</h3><p class="mini">Tick the validators that should run Ollama. Each selected validator can use a different active model, temperature, tagging style, and seed. Fresh rows start with intentionally different sampling profiles to reduce identical suggestions.</p><div class="lc-ai-default-model"><label class="field"><span>Default / new model tag</span><input id="lcPreFinalizeAiModel" value="qwen3:0.6b" placeholder="qwen3:0.6b"></label><button id="lcApplyAiModel" type="button">Use on checked</button></div><div id="lcPreFinalizeAiNodes"></div><div class="lc-endpoint-actions"><button id="lcInstallSelectedAi" type="button">Install / configure AI on checked validators</button></div><div id="lcPreFinalizeAiStatus" class="note">AI installation is optional. Finalize stays disabled while an AI install/model pull is running.</div></div><div class="lc-endpoint-actions"><button id="lcEndpointCancel" class="ghost" type="button">Cancel</button><button id="lcCopyEndpoints" type="button">Copy all</button><button id="lcEndpointContinue" class="danger" type="button">Continue finalization</button></div></section>`;document.body.appendChild(modal);$('lcEndpointClose').onclick=closeFinalizeEndpoints;$('lcEndpointCancel').onclick=closeFinalizeEndpoints;$('lcCopyEndpoints').onclick=copyFinalizeEndpoints;$('lcInstallSelectedAi').onclick=installSelectedAi;$('lcApplyAiModel').onclick=applyPrefinalDefaultModel;$('lcEndpointContinue').onclick=()=>{if(prefinalAiInstallBusy)return;closeFinalizeEndpoints();const n=$('finalize');if(n&&!n.disabled)n.click()};modal.querySelector('.lc-endpoint-backdrop').onclick=closeFinalizeEndpoints}
  const urls=finalizationEndpoints(lastState||{}),target=fleetView(lastState||{}).target,list=$('lcEndpointList'),go=$('lcEndpointContinue');
  list.innerHTML=urls.length?urls.map((u,i)=>`<div class="lc-endpoint-row"><span>${i+1}</span><code>${esc(u)}</code><button type="button" data-copy-endpoint="${esc(u)}">Copy</button></div>`).join(''):`<div class="note badbox">No managed gptcp1 endpoints are available yet.</div>`;
  for(const b of list.querySelectorAll('[data-copy-endpoint]'))b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copyEndpoint);const old=b.textContent;b.textContent='Copied';setTimeout(()=>b.textContent=old,1200)}catch{}};
  if(urls.length<target)list.insertAdjacentHTML('beforeend',`<div class="note warnbox">Only ${urls.length}/${target} managed endpoints are currently published. You can cancel and wait for all addresses before finalizing.</div>`);
  const fleet=fleetView(lastState||{}).fleet,aiNodes=$('lcPreFinalizeAiNodes'),defaultModel=localStorage.getItem('launchAiDefaultModel')||'qwen3:0.6b';
  const model=$('lcPreFinalizeAiModel');if(model)model.value=defaultModel;
  if(aiNodes)aiNodes.innerHTML=fleet.map((n,i)=>{const d=prefinalDiversityDefaults(i);return`<div class="lc-ai-config-row" data-ai-config-row="${i}"><label class="lc-ai-check"><input type="checkbox" data-ai-validator="${i}"><span><b>${esc(n.domain||String(n.pubkey||'').slice(0,14))}</b><small>${esc(n.pubkey||'')}</small></span></label><div class="lc-ai-config-grid"><label><span>Active model</span><input data-ai-model list="lcAiPrefinalModels-${i}" value="${esc(defaultModel)}" placeholder="qwen3:0.6b" autocomplete="off"><datalist id="lcAiPrefinalModels-${i}" data-ai-model-list>${prefinalModelOptions([],defaultModel,defaultModel)}</datalist></label><label><span>Temperature</span><input data-ai-temp type="number" min="0" max="2" step="0.05" value="${d.temperature}"></label><label><span>Tagging style</span><select data-ai-profile><option value="balanced">Balanced</option><option value="broad"${d.profile==='broad'?' selected':''}>Broad categories</option><option value="content"${d.profile==='content'?' selected':''}>Content / topic</option><option value="discovery"${d.profile==='discovery'?' selected':''}>Search / discovery</option></select></label><label><span>Seed</span><input data-ai-seed type="number" min="0" max="2147483647" step="1" value="0"></label></div><small class="lc-ai-node-note" data-ai-node-note>Checking installed models…</small></div>`}).join('');
  hydratePrefinalAiRows(fleet).catch(()=>{});
  if(go)go.disabled=!urls.length;const ta=$('lcEndpointCopyText');if(ta){ta.hidden=true;ta.value=urls.join('\n')}modal.hidden=false;
