  for(const n of nodes){const st=nodeStage(n,d),name=n.domain||n.host||String(n.pubkey||'').slice(0,16)||'managed node';html+=`<div class="lc-status-row ${st.kind}"><i></i><div><b>${esc(name)}</b><small>${esc(st.detail)}</small></div><span>${esc(st.label)}</span></div>`}
